mapper.update:
update qualified_manpower
set level_id = #{levelId,jdbcType=BIGINT},
  level_code = #{levelCode,jdbcType=VARCHAR},
  qualified_mp_num = #{qualifiedMpNum,jdbcType=INTEGER},
  qualified_mp_money = #{qualifiedMpMoney,jdbcType=DOUBLE}
where id = #{id,jdbcType=BIGINT}

mapper.select:
select a.* from qualified_manpower a where 1= 1
and level_code like CONCAT(CONCAT('%',#{levelCode,jdbcType=VARCHAR}), '%')
limit #{pageIndex}, #{pageSize}

select a.* from qualified_manpower a
where
a.level_id = #{id,jdbcType=BIGINT}
